import React, { useEffect, useRef, useState, useContext } from "react";
import { AuthContext } from "../Context/AuthContext";
import { eraseLine } from "../utils/erase";

function CanvasBoard({ socket }) {
  const canvasRef = useRef(null);
  const ctxRef = useRef(null);
  const { user } = useContext(AuthContext);

  const [drawing, setDrawing] = useState(false);
  const [lastPos, setLastPos] = useState(null);
  const [currentTool, setCurrentTool] = useState("pen");
  const [showClearNotification, setShowClearNotification] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    
    canvas.width = window.innerWidth - 200; // Account for user list sidebar
    canvas.height = window.innerHeight - 140; // Account for header and toolbar
    
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "white";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = "black";
    ctx.lineWidth = 2;
    ctxRef.current = ctx;

    // Handle window resize
    const handleResize = () => {
      canvas.width = window.innerWidth - 200;
      canvas.height = window.innerHeight - 140;
      ctx.fillStyle = "white";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const startDrawing = (e) => {
    if (user.role === "viewer") return;
    setDrawing(true);
    const { offsetX, offsetY } = e.nativeEvent;
    setLastPos({ x: offsetX, y: offsetY });
    ctxRef.current.beginPath();
    ctxRef.current.moveTo(offsetX, offsetY);
  };

  const draw = (e) => {
    if (!drawing || user.role === "viewer") return;
    const { offsetX, offsetY } = e.nativeEvent;
    const ctx = ctxRef.current;
    if (!lastPos) return;

    // Draw locally first for instant feedback
    if (currentTool === "eraser") {
      eraseLine(ctx, lastPos.x, lastPos.y, offsetX, offsetY);
    } else {
      ctx.globalCompositeOperation = "source-over";
      ctx.strokeStyle = "black";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(lastPos.x, lastPos.y);
      ctx.lineTo(offsetX, offsetY);
      ctx.stroke();
      ctx.closePath();
    }

    // Emit drawing info to server
    socket.emit("draw", {
      x0: lastPos.x,
      y0: lastPos.y,
      x1: offsetX,
      y1: offsetY,
      tool: currentTool,
    });

    setLastPos({ x: offsetX, y: offsetY });
  };

  const stopDrawing = () => {
    setDrawing(false);
    setLastPos(null);
    if (ctxRef.current) {
      ctxRef.current.closePath();
    }
  };

  useEffect(() => {
    const receiveDraw = (data) => {
      const ctx = ctxRef.current;
      if (!ctx) return;

      if (data.tool === "eraser") {
        eraseLine(ctx, data.x0, data.y0, data.x1, data.y1);
      } else {
        ctx.globalCompositeOperation = "source-over";
        ctx.strokeStyle = "black";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(data.x0, data.y0);
        ctx.lineTo(data.x1, data.y1);
        ctx.stroke();
        ctx.closePath();
      }
    };

    // Listen for clear board events from server
    const handleClearBoard = () => {
      const canvas = canvasRef.current;
      if (canvas) {
        const ctx = canvas.getContext("2d");
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "white";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        
        // Show notification
        setShowClearNotification(true);
        setTimeout(() => setShowClearNotification(false), 3000);
      }
    };

    socket.on("draw", receiveDraw);
    socket.on("clearBoard", handleClearBoard);

    return () => {
      socket.off("draw", receiveDraw);
      socket.off("clearBoard", handleClearBoard);
    };
  }, [socket]);

  const handleClearBoard = () => {
    if (user.role !== "admin") return;
    
    // Emit clear board event to server so all users get cleared
    socket.emit("clearBoard");
    
    // Also clear locally for immediate feedback
    const canvas = canvasRef.current;
    if (canvas) {
      const ctx = canvas.getContext("2d");
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "white";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
  };

  return (
    <div className="flex flex-col h-full">
      {/* Enhanced Tool Bar */}
      <div className="flex justify-center p-4 bg-gradient-to-r from-gray-100 to-blue-100 border-b border-gray-200 shadow-sm">
        <div className="flex items-center space-x-3 bg-white/70 backdrop-blur-sm rounded-2xl p-2 shadow-lg border border-white/50">
          <button
            onClick={() => setCurrentTool("pen")}
            className={`px-6 py-3 rounded-xl font-medium transition-all duration-200 transform hover:scale-105 ${
              currentTool === "pen" 
                ? "bg-gradient-to-r from-blue-500 to-purple-600 text-white shadow-lg" 
                : "bg-white/80 text-gray-700 hover:bg-gray-100 border border-gray-200"
            }`}
          >
            <div className="flex items-center space-x-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
              </svg>
              <span>Pen</span>
            </div>
          </button>
          
          <button
            onClick={() => setCurrentTool("eraser")}
            className={`px-6 py-3 rounded-xl font-medium transition-all duration-200 transform hover:scale-105 ${
              currentTool === "eraser" 
                ? "bg-gradient-to-r from-blue-500 to-purple-600 text-white shadow-lg" 
                : "bg-white/80 text-gray-700 hover:bg-gray-100 border border-gray-200"
            }`}
          >
            <div className="flex items-center space-x-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
              <span>Eraser</span>
            </div>
          </button>
          
          {user.role === "admin" && (
            <button
              onClick={handleClearBoard}
              className="px-6 py-3 bg-gradient-to-r from-red-500 to-pink-600 text-white rounded-xl font-medium hover:from-red-600 hover:to-pink-700 transition-all duration-200 transform hover:scale-105 shadow-lg"
            >
              <div className="flex items-center space-x-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
                <span>Clear Board</span>
              </div>
            </button>
          )}
        </div>
      </div>
      
      {/* Canvas Container */}
      <div className="flex-1 flex justify-center items-center bg-gradient-to-br from-gray-50 to-blue-50 p-4">
        <div className="relative">
          <canvas
            ref={canvasRef}
            className="border-2 border-gray-300 shadow-2xl rounded-lg bg-white"
            onMouseDown={startDrawing}
            onMouseMove={draw}
            onMouseUp={stopDrawing}
            onMouseLeave={stopDrawing}
            style={{
              backgroundColor: "white",
              cursor: currentTool === "eraser" ? "crosshair" : "pointer",
            }}
          />
          
          {/* Canvas Info Overlay */}
          <div className="absolute top-4 left-4 bg-white/90 backdrop-blur-sm rounded-lg px-3 py-2 shadow-lg border border-gray-200">
            <div className="text-sm text-gray-600">
              <div className="font-medium">Current Tool: {currentTool === "pen" ? "✏️ Pen" : "🧽 Eraser"}</div>
              <div className="text-xs text-gray-500">Click and drag to draw</div>
            </div>
          </div>

          {/* Clear Board Notification */}
          {showClearNotification && (
            <div className="absolute top-4 right-4 bg-gradient-to-r from-red-500 to-pink-600 text-white px-4 py-2 rounded-lg shadow-lg border border-white/20 animate-pulse">
              <div className="flex items-center space-x-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
                <span className="font-medium">Board Cleared!</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default CanvasBoard;
